enum ENTITY = {South, Pedestrian, East, North, West};

% Arrival times (1=earliest, 2=second, 3=third)
array[ENTITY] of var 1..3: arrival;

% Order through intersection (1=first through, 5=last through)
array[ENTITY] of var 1..5: order;

% Constraint 6: South car arrives first
constraint arrival[South] = 1;

% Constraints 5 & 6: Pedestrian and East car arrive at the same moment, after South
constraint arrival[Pedestrian] = 2;
constraint arrival[East] = 2;

% Constraint 7: North car and West car arrive at the same moment, after Pedestrian and East car
constraint arrival[North] = 3;
constraint arrival[West] = 3;

% All entities go through in different order positions
constraint alldifferent(order);

% Rule 2: Generally, earlier arrival means earlier order
% Rule 1 exception: Pedestrian at eastern crosswalk goes before East car
% Rule 3: Ties broken by North, East, South, West priority

% South goes first (arrived first, no conflicts)
constraint order[South] = 1;

% Pedestrian goes before East car (Rule 1: pedestrian at eastern crosswalk)
constraint order[Pedestrian] < order[East];

% Pedestrian and East both go before North and West (arrived earlier)
constraint order[Pedestrian] < order[North];
constraint order[Pedestrian] < order[West];
constraint order[East] < order[North];
constraint order[East] < order[West];

% North goes before West (Rule 3: clockwise priority North before West in tie)
constraint order[North] < order[West];

