enum ENTITY = {South, Pedestrian, East, North, West};

% Decision variables: order in which each entity goes through (1..5)
array[ENTITY] of var 1..5: go_order;

% All entities go in distinct order positions
constraint alldifferent(go_order);

% Arrival times (1=earliest, 3=latest)
array[ENTITY] of int: arrival = [1, 2, 2, 3, 3];
% South=1, Pedestrian=2, East=2, North=3, West=3

% Rule 1: Pedestrian at eastern crosswalk goes before East car
constraint go_order[Pedestrian] < go_order[East];

% Rule 2: Earlier arrivals go first (with Rule 1 exception already handled)
% For entities with different arrival times, earlier arrival goes first
constraint go_order[South] < go_order[Pedestrian];
constraint go_order[South] < go_order[East];
constraint go_order[Pedestrian] < go_order[North];
constraint go_order[Pedestrian] < go_order[West];
constraint go_order[East] < go_order[North];
constraint go_order[East] < go_order[West];

% Rule 3: For ties in arrival, clockwise priority North -> East -> South -> West
% North and West arrive together (time 3), so North goes before West
constraint go_order[North] < go_order[West];

