enum ENTITY = {South_car, Pedestrian, East_car, North_car, West_car};

array[ENTITY] of var 1..5: order;

% All entities go in different positions
constraint alldifferent(order);

% Arrival times (1=first, 2=second, 3=third)
array[ENTITY] of int: arrival = [1, 2, 2, 3, 3];

% Rule 1: Pedestrian goes before East car (pedestrian at eastern crosswalk, East car from east)
constraint order[Pedestrian] < order[East_car];

% Rule 2: Earlier arrivals go before later arrivals (with exceptions from Rule 1)
% South (arrival 1) before Pedestrian and East_car (arrival 2)
constraint order[South_car] < order[Pedestrian];
constraint order[South_car] < order[East_car];

% Pedestrian and East_car (arrival 2) before North and West (arrival 3)
constraint order[Pedestrian] < order[North_car];
constraint order[Pedestrian] < order[West_car];
constraint order[East_car] < order[North_car];
constraint order[East_car] < order[West_car];

% Rule 3: When cars arrive at same time, priority is North, East, South, West
% North and West arrived together (arrival 3), so North before West
constraint order[North_car] < order[West_car];

