enum PERSON = {Priya, Sam};
enum OUTCOME = {Approved, CounterOffer, Denied};

% Individual credit scores
array[PERSON] of int: creditScore = [680, 750];

% Financial information
int: combinedMonthlyIncome = 9000;
int: combinedMonthlyDebt = 3200;
bool: requestExceedsLimit = true;

% Decision variables
var int: coupleCreditScore;
var 0.0..100.0: dtiRatio;
var OUTCOME: outcome;

% Rule 1: Couple's credit tier is the lower of the two scores
constraint coupleCreditScore = min(creditScore);

% Calculate DTI ratio
constraint dtiRatio = int2float(combinedMonthlyDebt) / int2float(combinedMonthlyIncome) * 100.0;

% Determine outcome based on rules
constraint 
  if coupleCreditScore < 600 then
    outcome = Denied
  elseif dtiRatio > 43.0 then
    outcome = Denied
  elseif requestExceedsLimit then
    outcome = CounterOffer
  else
    outcome = Approved
  endif;

